(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  // ---- Model ----

  function TodoModel(storageKey) {
    this.storageKey = storageKey;
    this.todos = JSON.parse(localStorage.getItem(storageKey) || '[]');
  }

  TodoModel.prototype.save = function () {
    localStorage.setItem(this.storageKey, JSON.stringify(this.todos));
  };

  TodoModel.prototype.add = function (title) {
    this.todos.push({
      id: Date.now() + Math.random(),
      title: title,
      completed: false
    });
    this.save();
  };

  TodoModel.prototype.remove = function (id) {
    this.todos = this.todos.filter(function (t) { return t.id !== id; });
    this.save();
  };

  TodoModel.prototype.toggle = function (id) {
    var todo = this.todos.filter(function (t) { return t.id === id; })[0];
    if (todo) {
      todo.completed = !todo.completed;
      this.save();
    }
  };

  TodoModel.prototype.toggleAll = function (completed) {
    this.todos.forEach(function (t) { t.completed = completed; });
    this.save();
  };

  TodoModel.prototype.clearCompleted = function () {
    this.todos = this.todos.filter(function (t) { return !t.completed; });
    this.save();
  };

  TodoModel.prototype.updateTitle = function (id, title) {
    var todo = this.todos.filter(function (t) { return t.id === id; })[0];
    if (todo) {
      todo.title = title;
      this.save();
    }
  };

  // ---- Controller ----

  function TodoController(model) {
    this.model = model;
    this.filter = 'all';
  }

  TodoController.prototype.getFilteredTodos = function () {
    if (this.filter === 'active') {
      return this.model.todos.filter(function (t) { return !t.completed; });
    }
    if (this.filter === 'completed') {
      return this.model.todos.filter(function (t) { return t.completed; });
    }
    return this.model.todos;
  };

  // ---- View ----

  function TodoView(controller) {
    this.controller = controller;
    this.todoList = document.querySelector('.todo-list');
    this.main = document.querySelector('.main');
    this.footer = document.querySelector('.footer');
    this.todoCount = document.querySelector('.todo-count');
    this.clearCompleted = document.querySelector('.clear-completed');
    this.toggleAll = document.querySelector('#toggle-all');
    this.newTodo = document.querySelector('.new-todo');
    this.filters = document.querySelector('.filters');

    this.bindEvents();
    this.render();
  }

  TodoView.prototype.bindEvents = function () {
    var self = this;

    // New todo
    this.newTodo.addEventListener('keypress', function (e) {
      if (e.keyCode === ENTER_KEY) {
        var title = self.newTodo.value.trim();
        if (title) {
          self.controller.model.add(title);
          self.newTodo.value = '';
          self.render();
        }
      }
    });

    // Toggle all
    this.toggleAll.addEventListener('change', function () {
      self.controller.model.toggleAll(self.toggleAll.checked);
      self.render();
    });

    // Clear completed
    this.clearCompleted.addEventListener('click', function () {
      self.controller.model.clearCompleted();
      self.render();
    });

    // Filters (routing)
    this.filters.addEventListener('click', function (e) {
      var link = e.target.closest('a');
      if (!link) return;
      var href = link.getAttribute('href');
      var filter = href.replace('#/', '') || 'all';
      self.controller.filter = filter;
      self.render();
    });

    // Listen for hash changes
    window.addEventListener('hashchange', function () {
      var hash = window.location.hash.replace('#/', '') || 'all';
      self.controller.filter = hash;
      self.render();
    });

    // Delegate todo item events
    this.todoList.addEventListener('click', function (e) {
      var li = e.target.closest('li');
      if (!li) return;
      var id = Number(li.dataset.id);

      if (e.target.classList.contains('toggle')) {
        self.controller.model.toggle(id);
        self.render();
      }

      if (e.target.classList.contains('destroy')) {
        self.controller.model.remove(id);
        self.render();
      }
    });

    this.todoList.addEventListener('dblclick', function (e) {
      var label = e.target.closest('label');
      if (!label) return;
      var li = label.closest('li');
      if (!li) return;
      self.editTodo(li);
    });

    this.todoList.addEventListener('focusout', function (e) {
      if (e.target.classList.contains('edit')) {
        var li = e.target.closest('li');
        if (li && li.classList.contains('editing')) {
          self.commitEdit(li);
        }
      }
    });

    this.todoList.addEventListener('keypress', function (e) {
      if (e.keyCode === ENTER_KEY && e.target.classList.contains('edit')) {
        var li = e.target.closest('li');
        if (li) self.commitEdit(li);
      }
    });

    this.todoList.addEventListener('keydown', function (e) {
      if (e.keyCode === ESCAPE_KEY && e.target.classList.contains('edit')) {
        var li = e.target.closest('li');
        if (li) self.cancelEdit(li);
      }
    });
  };

  TodoView.prototype.editTodo = function (li) {
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.value = li.querySelector('label').textContent;
    editInput.focus();
    editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
  };

  TodoView.prototype.commitEdit = function (li) {
    var editInput = li.querySelector('.edit');
    var title = editInput.value.trim();
    var id = Number(li.dataset.id);

    if (title) {
      this.controller.model.updateTitle(id, title);
      this.render();
    } else {
      this.controller.model.remove(id);
      this.render();
    }
  };

  TodoView.prototype.cancelEdit = function (li) {
    li.classList.remove('editing');
    var editInput = li.querySelector('.edit');
    var label = li.querySelector('label');
    editInput.value = label.textContent;
  };

  TodoView.prototype.render = function () {
    var self = this;
    var model = this.controller.model;
    var filtered = this.controller.getFilteredTodos();

    // Render todo items
    this.todoList.innerHTML = '';
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');

      li.innerHTML =
        '<div class="view">' +
          '<input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>' +
          '<label>' + self.escapeHtml(todo.title) + '</label>' +
          '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + self.escapeHtml(todo.title) + '">';
      self.todoList.appendChild(li);
    });

    // Main and footer visibility
    var hasTodos = model.todos.length > 0;
    this.main.style.display = hasTodos ? '' : 'none';
    this.footer.style.display = hasTodos ? '' : 'none';

    // Count
    var activeCount = model.todos.filter(function (t) { return !t.completed; }).length;
    this.todoCount.innerHTML =
      '<strong>' + activeCount + '</strong> ' +
      (activeCount === 1 ? 'item' : 'items') + ' left';

    // Toggle all
    var allCompleted = model.todos.length > 0 && model.todos.every(function (t) { return t.completed; });
    this.toggleAll.checked = allCompleted;

    // Clear completed
    var completedCount = model.todos.filter(function (t) { return t.completed; }).length;
    this.clearCompleted.style.display = completedCount > 0 ? '' : 'none';

    // Active filter link
    var filterLinks = this.filters.querySelectorAll('a');
    filterLinks.forEach(function (link) {
      var href = link.getAttribute('href').replace('#/', '') || 'all';
      if (href === self.controller.filter) {
        link.classList.add('selected');
      } else {
        link.classList.remove('selected');
      }
    });
  };

  TodoView.prototype.escapeHtml = function (text) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(text));
    return div.innerHTML;
  };

  // ---- Bootstrap ----

  document.addEventListener('DOMContentLoaded', function () {
    var model = new TodoModel(STORAGE_KEY);
    var controller = new TodoController(model);
    var view = new TodoView(controller);

    // Set initial filter from URL
    var hash = window.location.hash.replace('#/', '') || 'all';
    controller.filter = hash;
    view.render();
  });
})();

const { Given, When, Then, Before } = require('@cucumber/cucumber');
const assert = require('node:assert');

// ---- Helpers ----

function getTodoByTitle(doc, title) {
  var labels = doc.querySelectorAll('.todo-list li label');
  for (var i = 0; i < labels.length; i++) {
    if (labels[i].textContent === title) return labels[i].closest('li');
  }
  return null;
}

function simulateKeydown(el, keyCode) {
  var event = el.ownerDocument.createEvent('KeyboardEvent');
  event.initKeyboardEvent('keydown', true, true, null, '', 0, false, false, false, false);
  Object.defineProperty(event, 'keyCode', { value: keyCode });
  el.dispatchEvent(event);
  return event;
}

function simulateKeypress(el, keyCode) {
  var event = el.ownerDocument.createEvent('KeyboardEvent');
  event.initKeyboardEvent('keypress', true, true, null, '', 0, false, false, false, false);
  Object.defineProperty(event, 'keyCode', { value: keyCode });
  el.dispatchEvent(event);
  return event;
}

function triggerChange(el) {
  var event = el.ownerDocument.createEvent('HTMLEvents');
  event.initEvent('change', true, true);
  el.dispatchEvent(event);
}

function triggerBlur(el) {
  var event = el.ownerDocument.createEvent('HTMLEvents');
  event.initEvent('focusout', true, true);
  el.dispatchEvent(event);
}

// ---- Given ----

Given('the app is loaded', function () {
  // App is loaded in Before hook by world.js — nothing extra needed
  this.filterCache = undefined;
});

Given('I have a todo {string}', function (title) {
  var input = this.document.querySelector('.new-todo');
  input.value = title;
  simulateKeypress(input, 13);
});

Given('I have a completed todo {string}', function (title) {
  var input = this.document.querySelector('.new-todo');
  input.value = title;
  simulateKeypress(input, 13);
  var li = getTodoByTitle(this.document, title);
  if (li) {
    li.querySelector('.toggle').checked = true;
    triggerChange(li.querySelector('.toggle'));
  }
});

Given('the app is reloaded', function () {
  // Persist current state (localStorage already saved by model)
  // Then reload the app fresh
  this.disposeApp();
  this.loadApp();
  // Re-apply hash-based filter after reload
  this.navigate(this.window.location.hash);
});

// ---- When ----

When('I type {string} into the new todo input and press Enter', function (title) {
  var input = this.document.querySelector('.new-todo');
  input.value = title;
  simulateKeypress(input, 13);
});

When('I click the toggle checkbox for {string}', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Todo "' + title + '" not found');
  li.querySelector('.toggle').click();
});

When('I click the destroy button for {string}', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Todo "' + title + '" not found');
  li.querySelector('.destroy').click();
});

When('I double-click the label of {string}', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Todo "' + title + '" not found');
  var label = li.querySelector('label');
  var event = this.document.createEvent('MouseEvent');
  event.initEvent('dblclick', true, true);
  label.dispatchEvent(event);
});

When('I change the todo title to {string} and press Enter', function (title) {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert(editInput, 'No editing input found');
  editInput.value = title;
  simulateKeypress(editInput, 13);
});

When('I change the todo title to {string} and blur', function (title) {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert(editInput, 'No editing input found');
  editInput.value = title;
  triggerBlur(editInput);
});

When('I change the todo title to {string} and press Escape', function (title) {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert(editInput, 'No editing input found');
  editInput.value = title;
  simulateKeydown(editInput, 27);
});

When('I clear the todo title and press Enter', function () {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert(editInput, 'No editing input found');
  editInput.value = '';
  simulateKeypress(editInput, 13);
});

When('I set the todo title to {string} and press Enter', function (title) {
  var editInput = this.document.querySelector('.todo-list li.editing .edit');
  assert(editInput, 'No editing input found');
  editInput.value = title;
  simulateKeypress(editInput, 13);
});

When('I click {string}', function (buttonText) {
  if (buttonText === 'Clear completed') {
    this.document.querySelector('.clear-completed').click();
  } else if (buttonText === 'Toggle All') {
    this.document.querySelector('#toggle-all').click();
  }
});

When('I complete {string}', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Todo "' + title + '" not found');
  li.querySelector('.toggle').click();
});

When('I navigate to {string}', function (hash) {
  this.navigate(hash);
});

When('I hover over the todo {string}', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Todo "' + title + '" not found');
  // No real hover in happy-dom, but the destroy button is always rendered in DOM
});

// ---- Then ----

Then('I should see {string} in the todo list', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Expected to see "' + title + '" in the todo list but it was not found');
});

Then('I should not see {string} in the todo list', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(!li, 'Expected NOT to see "' + title + '" in the todo list but it was found');
});

Then('the new todo input should be cleared', function () {
  assert.strictEqual(this.document.querySelector('.new-todo').value, '');
});

Then('the todo list should be empty', function () {
  var items = this.document.querySelectorAll('.todo-list li');
  assert.strictEqual(items.length, 0, 'Expected empty todo list but found ' + items.length + ' items');
});

Then('the main section should be hidden', function () {
  var main = this.document.querySelector('.main');
  assert.strictEqual(main.style.display, 'none', 'Expected main section to be hidden');
});

Then('the main section should be visible', function () {
  var main = this.document.querySelector('.main');
  assert(main.style.display !== 'none', 'Expected main section to be visible');
});

Then('the footer should be hidden', function () {
  var footer = this.document.querySelector('.footer');
  assert.strictEqual(footer.style.display, 'none', 'Expected footer to be hidden');
});

Then('the footer should be visible', function () {
  var footer = this.document.querySelector('.footer');
  assert(footer.style.display !== 'none', 'Expected footer to be visible');
});

Then('the todo {string} should be marked as completed', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Todo "' + title + '" not found');
  assert(li.classList.contains('completed'), 'Expected "' + title + '" to have class "completed"');
  assert(li.querySelector('.toggle').checked, 'Expected toggle checkbox to be checked');
});

Then('the todo {string} should be active', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Todo "' + title + '" not found');
  assert(!li.classList.contains('completed'), 'Expected "' + title + '" to NOT have class "completed"');
  assert(!li.querySelector('.toggle').checked, 'Expected toggle checkbox to NOT be checked');
});

Then('the edit input for {string} should be focused', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Todo "' + title + '" not found');
  assert(li.classList.contains('editing'), 'Expected "' + title + '" to have class "editing"');
  var editInput = li.querySelector('.edit');
  assert(editInput === this.document.activeElement, 'Expected edit input to be focused');
});

Then('the todo count should show {string}', function (expected) {
  assert.strictEqual(this.document.querySelector('.todo-count').textContent.trim(), expected);
});

Then('the clear completed button should be hidden', function () {
  assert.strictEqual(this.document.querySelector('.clear-completed').style.display, 'none');
});

Then('the clear completed button should be visible', function () {
  assert(this.document.querySelector('.clear-completed').style.display !== 'none');
});

Then('both {string} and {string} should be completed', function (title1, title2) {
  var li1 = getTodoByTitle(this.document, title1);
  var li2 = getTodoByTitle(this.document, title2);
  assert(li1 && li2, 'Todos not found');
  assert(li1.classList.contains('completed'), 'Expected "' + title1 + '" to be completed');
  assert(li2.classList.contains('completed'), 'Expected "' + title2 + '" to be completed');
});

Then('both {string} and {string} should be active', function (title1, title2) {
  var li1 = getTodoByTitle(this.document, title1);
  var li2 = getTodoByTitle(this.document, title2);
  assert(li1 && li2, 'Todos not found');
  assert(!li1.classList.contains('completed'), 'Expected "' + title1 + '" to be active');
  assert(!li2.classList.contains('completed'), 'Expected "' + title2 + '" to be active');
});

Then('the toggle all checkbox should not be checked', function () {
  assert(!this.document.querySelector('#toggle-all').checked, 'Expected toggle-all to NOT be checked');
});

Then('the toggle all checkbox should be checked', function () {
  assert(this.document.querySelector('#toggle-all').checked, 'Expected toggle-all to be checked');
});

Then('the todo list should contain {string}', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Expected to find "' + title + '" in the todo list');
});

Then('the todo list should not contain {string}', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(!li, 'Expected NOT to find "' + title + '" in the todo list');
});

Then('the {string} filter link should have the selected class', function (filterName) {
  var links = this.document.querySelectorAll('.filters a');
  for (var i = 0; i < links.length; i++) {
    if (links[i].textContent.trim() === filterName) {
      assert(links[i].classList.contains('selected'), 'Expected "' + filterName + '" link to have selected class');
      return;
    }
  }
  assert(false, 'Filter link "' + filterName + '" not found');
});

Then('the {string} filter link should not have the selected class', function (filterName) {
  var links = this.document.querySelectorAll('.filters a');
  for (var i = 0; i < links.length; i++) {
    if (links[i].textContent.trim() === filterName) {
      assert(!links[i].classList.contains('selected'), 'Expected "' + filterName + '" link to NOT have selected class');
      return;
    }
  }
});

Then('the todo {string} should not be in editing mode', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Todo "' + title + '" not found');
  assert(!li.classList.contains('editing'), 'Expected "' + title + '" to NOT have class "editing"');
});

Then('the destroy button for {string} should be visible', function (title) {
  var li = getTodoByTitle(this.document, title);
  assert(li, 'Todo "' + title + '" not found');
  var destroy = li.querySelector('.destroy');
  assert(destroy, 'Destroy button not found for "' + title + '"');
  // The destroy button is always in the DOM; visibility is controlled by CSS (:hover).
  // In happy-dom, the element exists. The test confirms it's in the DOM.
});

