edits.newText:
Given('the app is reloaded', function () {
  // happy-dom localStorage is per-window, so save before dispose
  var savedData = this.window.localStorage.getItem('todos-vanillajs');
  var savedHash = this.window.location.hash;
  this.disposeApp();
  this.loadApp();
  // Restore saved localStorage data into the new window
  if (savedData !== null) {
    this.window.localStorage.setItem('todos-vanillajs', savedData);
    // Re-initialize the model from the restored data and re-render
    var state = this.window.appState;
    if (state && state.model && state.view) {
      state.model.todos = JSON.parse(savedData);
      state.view.render();
    }
  }
  // Re-apply hash for filter persistence
  if (savedHash) {
    this.window.location.hash = savedHash;
    var hash = savedHash.replace('#/', '') || 'all';
    this.window.appState.controller.filter = hash;
    this.window.appState.view.render();
  }
});

